<?php $groups = tr_section_groups(); tr_hero('Project sections', 'Every segment of the project in its own section', 'Each source JSON/document is treated as an owner section with record counts, Timeline families, rights review count, safety review count, and a drilldown page.'); ?>
<section class="source-list"><?php foreach ($groups as $g): ?><article class="source-card"><h2><a href="<?= tr_e(tr_url(['page'=>'section','source'=>$g['key']])); ?>"><?= tr_e($g['title']); ?></a></h2><p><code><?= tr_e($g['key']); ?></code></p><dl class="facts"><div><dt>Records</dt><dd><?= tr_e((string)$g['count']); ?></dd></div><div><dt>Families</dt><dd><?= tr_e(implode(', ', array_keys($g['families']))); ?></dd></div><div><dt>Rights review</dt><dd><?= tr_e((string)$g['needs_rights']); ?></dd></div><div><dt>Safety review</dt><dd><?= tr_e((string)$g['needs_safety']); ?></dd></div></dl><a class="button" href="<?= tr_e(tr_url(['page'=>'section','source'=>$g['key']])); ?>">Open section</a> <a class="button ghost" href="<?= tr_e(tr_source_url($g['key'])); ?>">Raw source</a></article><?php endforeach; ?></section>
